public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        String[] parts = reader.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int k = Integer.parseInt(parts[1]);
        int l = Integer.parseInt(parts[2]);
        int mod = 998244353;
        long[] invs = IntegerUtils.invs(2 * n + 3, mod);
        long[][] p = new long[2 * n + 1][n + 1];
        p[0][1] = 1;
        long answer = 0;
        for (int i = 1; i < 2 * n; i++) {
            int prevMax = Math.min(2 * n - i, i);
            int maxRunning = Math.min(2 * n - i - 1, i + 1);
            for (int j = 0; j <= prevMax; j++) {
                if (p[i - 1][j] != 0) {
                    if (j > 0) {
                        p[i][j - 1] = (p[i][j - 1] + p[i - 1][j] * j % mod * invs[2 * n - i] ) % mod;
                    }
                    if (j < maxRunning) {
                        p[i][j + 1] = (p[i][j + 1] + p[i - 1][j] * (2 * n - i - j) % mod * invs[2 * n - i]) % mod;
                    }
                    if (j >= k)
                        answer = (answer + p[i - 1][j]) % mod;
                }
            }
        }
        if (k <= 1)
            answer += p[2 * n - 1][1];
        answer = answer * l % mod * invs[2 * n + 1] % mod;
        writer.println(answer);
        writer.close();
    }

    static class IntegerUtils {
        public static long[] invs(int n, long p) {
            long[] res = new long[n];
            res[1] = 1;
            for (int i = 2; i < n; i++) {
                res[i] = (p - (p / i) * res[(int) (p % i)] % p) % p;
            }
            return res;
        }
    }
}
